const { chromium } = require('/tmp/avb-IpZaMN/project/node_modules/playwright');
(async () => {
  const b = await chromium.launch();
  for (const w of [1280, 390]) {
    const p = await b.newPage({ viewport: { width: w, height: 800 } });
    for (const n of ['index','products','pricing','orders','about','contact']) {
      await p.goto(`http://127.0.0.1:${process.env.PORT}/${n}.html`);
      await p.waitForLoadState('networkidle');
      await p.screenshot({ path: `${process.env.TMPDIR}/${n}-${w}.png`, fullPage: true });
      const ov = await p.evaluate(() => document.documentElement.scrollWidth);
      console.log(n, w, 'scrollWidth', ov);
